-- ARCHIVED V0.2 OPTION — NOT REQUIRED BY THE V0.3 ZAPIER TABLES ARCHITECTURE.
-- Retained so the prior Postgres design is available if future scale justifies it.
create extension if not exists pgcrypto;
create table if not exists organizations(id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz default now());
create table if not exists profiles(id uuid primary key, organization_id uuid references organizations(id), role text not null default 'office', created_at timestamptz default now());
create table if not exists clients(id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id), source text not null default 'jobber', external_id text, name text not null, email text, phone text, raw_payload jsonb default '{}'::jsonb, last_synced_at timestamptz, unique(organization_id,source,external_id));
create table if not exists leads(id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id), source text not null, external_id text, client_id uuid references clients(id), stage text not null default 'new', service text, estimated_value numeric, campaign text, adset text, ad text, raw_payload jsonb default '{}'::jsonb, created_at timestamptz default now(), unique(organization_id,source,external_id));
create table if not exists external_records(id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id), source text not null, entity_type text not null, external_id text not null, local_id uuid, raw_payload jsonb default '{}'::jsonb, last_synced_at timestamptz default now(), unique(organization_id,source,entity_type,external_id));
create table if not exists tasks(id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id), client_id uuid references clients(id), title text not null, status text not null default 'open', priority text not null default 'normal', assigned_to uuid, due_at timestamptz, source text default 'manual', created_at timestamptz default now());
create table if not exists activities(id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id), client_id uuid references clients(id), event_type text not null, source text not null, summary text, metadata jsonb default '{}'::jsonb, occurred_at timestamptz not null default now());
create table if not exists integration_events(id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id), event_key text unique not null, source text not null, event_type text not null, entity_type text, external_id text, payload jsonb not null, status text not null default 'received', error text, received_at timestamptz default now(), processed_at timestamptz);
create table if not exists automation_rules(id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id), name text not null, enabled boolean not null default true, trigger jsonb not null, conditions jsonb default '[]'::jsonb, actions jsonb not null, created_at timestamptz default now());
create table if not exists automation_runs(id uuid primary key default gen_random_uuid(), rule_id uuid references automation_rules(id), event_id uuid references integration_events(id), status text not null, output jsonb default '{}'::jsonb, started_at timestamptz default now(), completed_at timestamptz);
create table if not exists ai_tool_calls(id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id), user_id uuid, tool_name text not null, risk text not null, arguments jsonb default '{}'::jsonb, result jsonb, status text not null, created_at timestamptz default now());
create table if not exists ai_approvals(id uuid primary key default gen_random_uuid(), tool_call_id uuid references ai_tool_calls(id), status text not null default 'pending', approved_by uuid, approved_at timestamptz, created_at timestamptz default now());
